import math

def get_prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau(n):
    if n == 1:
        return 1
    factors = get_prime_factorization(n)
    return math.prod([e + 1 for e in factors.values()])

def calculate_tau_n_pow_12(n):
    if n == 1:
        return 1

    # n = p1^a1 * p2^a2 * ...
    factors_n = get_prime_factorization(n)

    # tau(n^12) = tau(p1^(12*a1) * p2^(12*a2) * ...)
    # tau(n^12) = (12*a1 + 1) * (12*a2 + 1) * ...

    tau_n_pow_12 = 1
    for exponent_a in factors_n.values():
        tau_n_pow_12 *= (12 * exponent_a + 1)

    return tau_n_pow_12

# --- Task 1: Verification of known solutions ---
known_solutions = [1, 13, 25, 325]
verification_results = {}
print("--- Verification of Known Solutions ---")
for n in known_solutions:
    lhs = n
    rhs = calculate_tau_n_pow_12(n)
    is_solution = lhs == rhs
    verification_results[n] = (lhs, rhs, is_solution)
    print(f"n={n}: LHS={lhs}, RHS={rhs}, Match={is_solution}")

# --- Task 2: Check all integers from 1 to 1000 ---
print("\n--- Checking Integers n from 1 to 1000 ---")
found_solutions_small_range = []
for n in range(1, 1001):
    lhs = n
    rhs = calculate_tau_n_pow_12(n)
    if lhs == rhs:
        found_solutions_small_range.append(n)

print(f"\nSolutions found in range [1, 1000]: {found_solutions_small_range}")

